  margin-top: 20px;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 28px;
}

.hero-facts {
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  margin-top: clamp(28px, 4vw, 44px);
  border-top: 1px solid var(--line);
  padding-top: 18px;
}

.hero-facts__item {
  padding-right: clamp(16px, 2.4vw, 30px);
  margin-right: clamp(16px, 2.4vw, 30px);
  border-right: 1px solid var(--line);
}

.hero-facts__item:last-child {
  border-right: 0;
  margin-right: 0;
  padding-right: 0;
}

.hero-facts dt {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-3);
}

.hero-facts dd {
  margin-top: 3px;
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--ink-2);
}

.hero-visual {
  position: relative;
  min-width: 0;
}

.hero-blob {
  position: absolute;
  top: -14%;
  right: -16%;
  width: 88%;
  aspect-ratio: 1;
  background:
    radial-gradient(circle at 36% 32%, color-mix(in oklab, var(--primary) 26%, transparent), transparent 64%),
    radial-gradient(circle at 74% 72%, color-mix(in oklab, var(--secondary) 16%, transparent), transparent 62%);
  filter: blur(10px);
  opacity: 0.95;
  border-radius: 46% 54% 58% 42% / 44% 46% 54% 56%;
  animation: morph 22s var(--ease-in-out) infinite alternate;
  filter: blur(2px);
}

[data-theme='dark'] .hero-blob {
  opacity: 0.9;
}

@keyframes morph {
=== base reveal ===
    border-color var(--dur-2) var(--ease-out),
    box-shadow var(--dur-3) var(--ease-out),
    background-color var(--dur-2) var(--ease-out);
}

.card--interactive:hover {
  transform: translateY(-3px);
  border-color: var(--card-edge-hover);
  box-shadow: var(--card-shadow-hover);
}

/* ---------- scroll reveal ---------- */

.reveal {
  opacity: 0;
  transition:
    opacity 0.7s var(--ease-out),
    transform 1s var(--ease-spring);
  transition-delay: var(--reveal-delay, 0ms);
}

/* text and small blocks */
.reveal--up {
  transform: translateY(20px);
}

.reveal--soft {
  transform: translateY(10px);
}

/* windows and cards: they rise into place and settle */
.reveal--window {
  transform: translateY(34px) scale(0.965);
  transition-duration: 0.85s, 1.15s;
}

.reveal.is-in {
  opacity: 1;
  transform: none;
}

/* ---------- scrollbar ---------- */

@supports (scrollbar-width: thin) {
  * {
    scrollbar-width: thin;
    scrollbar-color: var(--line-strong) transparent;
  }
}

::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-thumb {
  background: var(--line-strong);
  border: 3px solid transparent;
  background-clip: content-box;
  border-radius: 999px;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .reveal {
    opacity: 1;
    transform: none;
  }
}

