    };
    await wait(800);
    const after = {
      theme: root.dataset.theme,
      color: getComputedStyle(document.body).backgroundColor,
      cls: root.className,
      vars: root.style.getPropertyValue('--theme-x'),
      storage: localStorage.getItem('exd-theme')
    };
    return { before, during, after };
  })()`
})
