    t.ready.then(() => log.push('ready'), (e) => log.push('ready-rejected:' + e));
    t.updateCallbackDone.then(() => log.push('update-done'), (e) => log.push('update-rejected:' + e));
    t.finished.then(() => log.push('finished'), (e) => log.push('finished-rejected:' + e));
    await wait(60);
    log.push('anims@60:' + document.getAnimations().map(a => (a.animationName || a.transitionProperty || '?') + '|' + (a.pseudoElement || '')).join(','));
    await wait(400);
    log.push('anims@460:' + document.getAnimations().map(a => (a.animationName || a.transitionProperty || '?') + '|' + (a.pseudoElement || '')).join(','));
    await wait(400);
    return { log };
  })()`
})
