(async () => {
    const wait = (ms) => new Promise(r => setTimeout(r, ms));
    const root = document.documentElement;
    const original = document.startViewTransition;
    document.startViewTransition = undefined;
    const before = { theme: root.dataset.theme, cls: root.className };
    document.querySelector('.theme-toggle').click();
    await wait(60);
    const during = { theme: root.dataset.theme, cls: root.className, color: getComputedStyle(document.body).backgroundColor, storage: localStorage.getItem('exd-theme') };
    await wait(500);
    const after = { theme: root.dataset.theme, cls: root.className, color: getComputedStyle(document.body).backgroundColor };
    document.startViewTransition = original;
    return { before, during, after };
  })()

