const tabID = "tab_3270d559-48d2-4dec-b053-da01b34aed2c"
await tools.browser.reload({ tabID })
await tools.browser.wait({ tabID, condition: "load" })
const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const wait = (ms) => new Promise(r => setTimeout(r, ms));
    const rafOk = () => new Promise(resolve => {
      const t = setTimeout(() => resolve(false), 400);
      requestAnimationFrame(() => { clearTimeout(t); resolve(true); });
    });
    let raf = false;
    for (let i = 0; i < 10 && !raf; i++) { raf = await rafOk(); if (!raf) await wait(100); }
    await wait(400);

    const root = document.documentElement;
    const before = { theme: root.dataset.theme, bg: getComputedStyle(document.body).backgroundColor };
    const t0 = performance.now();
    document.querySelector('.theme-toggle').click();
    await wait(100);
    const during = {
      theme: root.dataset.theme,
      bg: getComputedStyle(document.body).backgroundColor,
      vars: ['--theme-x','--theme-y','--theme-r'].map(v => root.style.getPropertyValue(v)),
      anims: document.getAnimations()
        .filter(a => (a.animationName || '').includes('theme-reveal') || (a.animationName || '').includes('ua-view-transition'))
        .map(a => ({ n: a.animationName, state: a.playState, time: Math.round(a.currentTime || 0), dur: a.effect?.getTiming().duration }))
    };
    await wait(700);
    const after = {
      theme: root.dataset.theme,
      bg: getComputedStyle(document.body).backgroundColor,
      vars: ['--theme-x','--theme-y','--theme-r'].map(v => root.style.getPropertyValue(v)),
      storage: localStorage.getItem('exd-theme')
    };
    return { raf, before, during, after, ms: Math.round(performance.now() - t0) };
  })()`
})
const errors = await tools.browser.console({ tabID, level: "error" })
return { value: res.value, errors: errors.messages?.slice(-8) }

