  display: block;
  transform:
    translate3d(calc(var(--mx) * var(--shift-x)), calc(var(--my) * var(--shift-y)), 0)
    rotate(calc(var(--mx) * var(--tilt)));
  transition: transform 0.55s var(--ease-out);
  animation: hero-float var(--float-dur) var(--ease-in-out) var(--float-delay) infinite alternate;
  will-change: transform;
}

.hero-title__line--accent {
