const tabID = "tab_3270d559-48d2-4dec-b053-da01b34aed2c"
await tools.browser.navigate({ tabID, url: "http://localhost:5173/" })
await tools.browser.wait({ tabID, condition: "load" })
const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const wait = (ms) => new Promise(r => setTimeout(r, ms));
    let raf = false;
    for (let i = 0; i < 10 && !raf; i++) {
      raf = await new Promise(resolve => {
        const t = setTimeout(() => resolve(false), 300);
        requestAnimationFrame(() => { clearTimeout(t); resolve(true); });
      });
      if (!raf) await wait(100);
    }
    await wait(300);
    const hero = document.querySelector('.hero');
    const title = document.querySelector('.hero-title');
    const lines = [...document.querySelectorAll('.hero-title__line')];
    const read = () => ({
      mx: title.style.getPropertyValue('--mx'),
      my: title.style.getPropertyValue('--my'),
      transforms: lines.map(l => getComputedStyle(l).transform),
      floats: document.getAnimations().filter(a => a.animationName === 'hero-float').map(a => ({ s: a.playState, d: a.effect.getTiming().duration })),
      enterTransforms: [...document.querySelectorAll('.hero-title__word')].map(w => ({ cls: w.className, t: getComputedStyle(w).transform }))
    });
    const before = read();
    const rect = hero.getBoundingClientRect();
    hero.dispatchEvent(new PointerEvent('pointermove', {
      pointerType: 'mouse',
      clientX: rect.right - 10,
      clientY: rect.top + 10,
      bubbles: true
    }));
    await wait(120);
    const rightTop = read();
    hero.dispatchEvent(new PointerEvent('pointermove', {
      pointerType: 'mouse',
      clientX: rect.left + 10,
      clientY: rect.bottom - 10,
      bubbles: true
    }));
    await wait(120);
    const leftBottom = read();
    hero.dispatchEvent(new PointerEvent('pointerleave', { pointerType: 'mouse', bubbles: true }));
    await wait(120);
    const reset = read();
    return { raf, before, rightTop, leftBottom, reset };
  })()`
})
return res.value

