  script: `(() => {
    const hero = document.querySelector('.hero');
    const title = document.querySelector('.hero-title');
    const lines = [...document.querySelectorAll('.hero-title__line')];
    const orig = window.requestAnimationFrame;
    window.requestAnimationFrame = (cb) => { cb(performance.now()); return 0; };
    const rect = hero.getBoundingClientRect();
    const fire = (x, y) => hero.dispatchEvent(new PointerEvent('pointermove', { pointerType: 'mouse', clientX: x, clientY: y, bubbles: true }));
    const read = () => ({
      mx: title.style.getPropertyValue('--mx'),
      my: title.style.getPropertyValue('--my'),
      transforms: lines.map(l => getComputedStyle(l).transform)
    });
    fire(rect.right, rect.top);
    const topRight = read();
    fire(rect.left, rect.bottom);
    const bottomLeft = read();
    hero.dispatchEvent(new PointerEvent('pointerleave', { pointerType: 'mouse', bubbles: true }));
    const reset = read();
    window.requestAnimationFrame = orig;
    return { topRight, bottomLeft, reset };
  })()`
})
return res.value

