const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const wait = (ms) => new Promise(r => setTimeout(r, ms));
    const b = document.querySelector('.hero-actions .btn');
    const anims = () => document.getAnimations().filter(a => a.animationName === 'control-float').map(a => ({ t: Math.round(a.currentTime || 0), s: a.playState }));
    const out = [{ translate: getComputedStyle(b).translate, anims: anims() }];
    await wait(800);
    out.push({ translate: getComputedStyle(b).translate, anims: anims() });
    await wait(800);
    out.push({ translate: getComputedStyle(b).translate, anims: anims() });
    return out;
  })()`
})
return res.value

