    const read = () => ({ hover: b.matches(':hover'), transform: getComputedStyle(b).transform, translate: getComputedStyle(b).translate, anim: getComputedStyle(b).animationName });
    const out = [read()];
    await wait(500);
    out.push(read());
    return out;
  })()`
})
return { ref, value: res.value }

