.builder__note {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 24px;
  font-size: 0.76rem;
  color: var(--ink-3);
}

/* --- live mock --- */

.mock {
  --m-bg: #1b1714;
  --m-side: #15120f;
  --m-panel: #221d18;
  --m-bubble: #2a231d;
  --m-ink: #f4f0ea;
  --m-ink-2: #a49c92;
  --m-line: rgb(255 255 255 / 0.08);
  display: grid;
  grid-template-columns: 46px 172px minmax(0, 1fr);
  height: 372px;
  border-radius: 20px;
  border: var(--window-edge-w, 3px) solid var(--window-edge);
  background: var(--m-bg);
  color: var(--m-ink);
  overflow: hidden;
  box-shadow: var(--shadow-2);
  font-size: 0.7rem;
  line-height: 1.35;
}

.mock[data-mock='light'] {
  --m-bg: #ffffff;
  --m-side: #f6f3ee;
  --m-panel: #f0ece5;
  --m-bubble: #f0ece5;
  --m-ink: #171410;
  --m-ink-2: #7b7368;
  --m-line: rgb(23 20 16 / 0.08);
}

.mock__rail {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  background: var(--m-side);
  border-right: 1px solid var(--m-line);
}

.mock__avatar {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  flex: none;
  border-radius: 50%;
  font-size: 0.62rem;
  font-weight: 700;
  overflow: hidden;
}

.mock__avatar--brand img {
  width: 100%;
  height: 100%;
}

.mock__avatar--a {
  background: #2f6fd0;
  color: #fff;
}

.mock__avatar--b {
  background: #8a5f14;
  color: #fff;
}

.mock__avatar--brand {
  width: 30px;
  height: 30px;
}

.mock__rail-dot {
  width: 22px;
  height: 22px;
  border-radius: 8px;
  background: color-mix(in oklab, var(--m-ink) 10%, transparent);
}

.mock__rail-dot--accent {
  background: var(--m-accent);
  margin-top: 6px;
}

.mock__rail-spacer {
  flex: 1;
}

.mock__side {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px 8px;
  background: var(--m-side);
  border-right: 1px solid var(--m-line);
  overflow: hidden;
}

.mock__search {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding-inline: 9px;
  margin-bottom: 8px;
  border-radius: var(--r-pill);
  background: color-mix(in oklab, var(--m-ink) 6%, transparent);
  color: var(--m-ink-2);
  font-size: 0.64rem;
