const tabID = "tab_3270d559-48d2-4dec-b053-da01b34aed2c"
await tools.browser.reload({ tabID })
await tools.browser.wait({ tabID, condition: "load" })
const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const wait = (ms) => new Promise(r => setTimeout(r, ms));
    await wait(400);
    const builder = document.querySelector('.builder');
    builder.scrollIntoView({ block: 'center', behavior: 'instant' });
    const mock = document.querySelector('.mock');
    const buttons = [...builder.querySelectorAll('.segmented__btn')];
    const bg = () => getComputedStyle(mock).backgroundColor;
    const before = { theme: mock.dataset.mock, bg: bg(), btn: buttons.map(b => b.textContent.trim()) };
    const light = buttons.find(b => b.getAttribute('aria-pressed') === 'false' || b.textContent.toLowerCase().includes('свет'));
    light.click();
    await wait(80);
    const during = {
      theme: mock.dataset.mock,
      bg: bg(),
      transitions: document.getAnimations()
        .filter(a => a.transitionProperty)
        .map(a => ({ p: a.transitionProperty, t: Math.round(a.currentTime || 0), s: a.playState, target: a.effect?.target?.className }))
        .filter(a => String(a.target).includes('mock') || String(a.target).includes('mock'))
        .slice(0, 8),
      count: document.getAnimations().filter(a => a.transitionProperty).length
    };
    await wait(600);
    const after = { theme: mock.dataset.mock, bg: bg() };
    return { before, during, after, reduce: matchMedia('(prefers-reduced-motion: reduce)').matches };
  })()`
})
const errors = await tools.browser.console({ tabID, level: "error" })
return { value: res.value, errors: errors.messages?.slice(-5) }

