        .filter(a => a.transitionProperty)
        .map(a => ({ p: a.transitionProperty, t: Math.round(a.currentTime || 0), s: a.playState, target: a.effect?.target?.className }))
        .filter(a => String(a.target).includes('mock') || String(a.target).includes('mock'))
        .slice(0, 8),
      count: document.getAnimations().filter(a => a.transitionProperty).length
    };
    await wait(600);
    const after = { theme: mock.dataset.mock, bg: bg() };
    return { before, during, after, reduce: matchMedia('(prefers-reduced-motion: reduce)').matches };
  })()

