const tabID = "tab_3270d559-48d2-4dec-b053-da01b34aed2c"
const res = await tools.browser.evaluate({
  tabID,
  script: `(() => {
    const q = (s) => document.querySelector(s);
    const info = (el, name) => {
      if (!el) return { name, missing: true };
      const cs = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      return {
        name,
        rect: { x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1) },
        transform: cs.transform,
        border: cs.border,
        borderRadius: cs.borderRadius,
        boxShadow: cs.boxShadow.slice(0, 80),
        background: cs.backgroundColor,
        outline: cs.outline,
        overflow: cs.overflow,
        pseudoBefore: getComputedStyle(el, '::before').content,
        pseudoAfter: getComputedStyle(el, '::after').content
      };
    };
    return {
      tilt: info(q('.builder-tilt'), 'tilt'),
