/* ------------------------------------------------------------------
   App shell and ambient Material shapes
------------------------------------------------------------------ */

.app-shell {
  position: relative;
  isolation: isolate;
  z-index: 0;
}

.backdrop {
  position: fixed;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  pointer-events: none;
  opacity: 0.9;
}

.backdrop__layer {
  position: absolute;
  inset: 0;
}

/* each shape travels with its own scene layer */
.backdrop__flight {
  position: absolute;
  top: var(--t);
  left: var(--l);
  animation: backdrop-in 0.85s var(--ease-out) both;
  animation-delay: var(--stagger, 0ms);
  will-change: transform, opacity;
}

.backdrop__layer.is-leaving .backdrop__flight {
  animation: backdrop-out 0.62s var(--ease-in-out) both;
  animation-delay: calc(var(--stagger, 0ms) * 0.35);
}

