content.text:
  margin-top: clamp(28px, 4vw, 44px);
  border-top: 1px solid var(--line);
  padding-top: 18px;
}

.hero-facts__item {
  padding-right: clamp(16px, 2.4vw, 30px);
  margin-right: clamp(16px, 2.4vw, 30px);
  border-right: 1px solid var(--line);
}

.hero-facts__item:last-child {
  border-right: 0;
  margin-right: 0;
  padding-right: 0;
}

.hero-facts dt {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-3);
}

.hero-facts dd {
  margin-top: 3px;
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--ink-2);
}

.hero-visual {
  position: relative;
  min-width: 0;
}

.hero-blob {
  position: absolute;
  top: -14%;
  right: -16%;
  width: 88%;
  aspect-ratio: 1;
  background:
    radial-gradient(circle at 36% 32%, color-mix(in oklab, var(--primary) 26%, transparent), transparent 64%),
    radial-gradient(circle at 74% 72%, color-mix(in oklab, var(--secondary) 16%, transparent), transparent 62%);
  filter: blur(10px);
  opacity: 0.95;
  border-radius: 46% 54% 58% 42% / 44% 46% 54% 56%;
  animation: morph 22s var(--ease-in-out) infinite alternate;
  filter: blur(2px);
}

[data-theme='dark'] .hero-blob {
  opacity: 0.9;
}

@keyframes morph {
  0% {
    border-radius: 46% 54% 58% 42% / 44% 46% 54% 56%;
    transform: rotate(0deg) scale(1);
  }
  50% {
    border-radius: 58% 42% 44% 56% / 56% 58% 42% 44%;
    transform: rotate(9deg) scale(1.04);
  }
  100% {
    border-radius: 42% 58% 52% 48% / 48% 42% 58% 52%;
    transform: rotate(-6deg) scale(0.99);
  }
}

.app-window {
  position: relative;
  border-radius: 20px;
  border: var(--window-edge-w, 3px) solid var(--window-edge);
  background: var(--window-bg);
  box-shadow: var(--shadow-3);
  overflow: hidden;
}

.app-window__shot-wrap {
  overflow: hidden;
}

/* The source screenshots carry a promo backdrop; zoom past it. */
.app-window__shot {
  width: 100%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
  object-position: center;
  transform: scale(1.1);
}

.app-window__dots {
  display: inline-flex;
  gap: 6px;
}

.app-window__dots i {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--line-strong);
}

.hero-badge {
  position: absolute;
  left: -16px;
  bottom: -18px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 16px 7px 7px;
  border-radius: var(--r-pill);
  background: var(--surface);
  box-shadow: var(--shadow-2);
  font-size: 0.78rem;
  color: var(--ink-2);
}

.hero-badge__ico {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--primary-container);
  color: var(--on-primary-container);
}

.hero-badge b {
  color: var(--ink);
  font-weight: 600;
}

.hero-scroll {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  align-self: flex-start;

