+   * and a translucent/backdrop-filtered layer shimmers at its rounded edges
+   * while the card is transformed.
+   */
+  background-color: color-mix(in oklab, var(--surface-1) 62%, var(--bg));
   border: 1.5px solid transparent;
   box-shadow: var(--card-shadow);
-  backdrop-filter: var(--glass-blur);
-  -webkit-backdrop-filter: var(--glass-blur);
 }

 .card--flat {
@@ -513,6 +594,78 @@ ol {
   }
