+/* ---------- click ripple ---------- */
+
+.click-ripple {
+  position: fixed;
+  z-index: 96;
+  width: 16px;
+  height: 16px;
+  margin: -8px 0 0 -8px;
+  border-radius: 50%;
+  background: color-mix(in oklab, var(--primary) 42%, transparent);
+  pointer-events: none;
+  opacity: 0;
+  animation: click-ripple 620ms var(--ease-out) forwards;
+  will-change: transform, opacity;
+}
+
+@keyframes click-ripple {
+  0% {
+    opacity: 0.55;
+    transform: scale(0.35);
+  }
+  60% {
+    opacity: 0.26;
+  }
+  100% {
+    opacity: 0;
+    transform: scale(6.5);
+  }
+}
+
+@media (pointer: coarse) {
+  .click-ripple {
+    display: none;
+  }
+}
+
+/* ---------- theme switch ---------- */
+
+/* the new palette spreads from the toggle button */
+::view-transition-old(root),
+::view-transition-new(root) {
+  animation: none;
+  mix-blend-mode: normal;
+}
+
+::view-transition-old(root) {
+  z-index: 1;
+}
+
+::view-transition-new(root) {
+  z-index: 2;
+  clip-path: circle(0% at var(--theme-x, 100%) var(--theme-y, 0%));
+  animation: theme-reveal 560ms var(--ease-out) both;
+}
+
+@keyframes theme-reveal {
+  to {
+    clip-path: circle(var(--theme-r, 150vmax) at var(--theme-x, 100%) var(--theme-y, 0%));
+  }
+}
+
+/* fallback without View Transitions: ease every surface to the new palette */
+html.theme-switching *,
+html.theme-switching *::before,

