  --my: 50%;
  position: relative;
  border-radius: var(--tilt-r, 22px);
  transform: perspective(1200px) rotateX(var(--rx)) rotateY(var(--ry));
  transition: transform 0.55s var(--ease-out);
  will-change: transform;
}

.tilt.is-tilting {
  transition: transform 0.1s linear;
}

.tilt__inner {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  transition: transform 0.65s var(--ease-spring);
  transform-origin: center;
}

/*
 * No fractional hover scale here: it forces the browser to resample the
 * anti-aliased rounded corners of every window while the card tilts, which
 * reads as broken/stepped edges. The tilt and the cursor sheen stay.
 */

